package cn.pawday.integration;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
class V32MigrationTests {
 @Test void upgradeFromV034DoesNotInventInventoryOrExternalFacts()throws Exception{try(var pg=EmbeddedPostgres.builder().start()){var ds=pg.getPostgresDatabase();var db=new JdbcTemplate(ds);Flyway.configure().dataSource(ds).target("34").load().migrate();UUID m=UUID.randomUUID(),store=UUID.randomUUID(),brand=UUID.randomUUID(),spu=UUID.randomUUID(),sku=UUID.randomUUID(),offer=UUID.randomUUID(),actor=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST_ONLY upgrade','ACTIVE')",m);db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST_ONLY store')",store,m);db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,'TEST_ONLY','TEST_ONLY')",actor,m);db.update("INSERT INTO brands(id,name,source_ref) VALUES (?,'TEST_ONLY','TEST_ONLY')",brand);db.update("INSERT INTO spus(id,brand_id,name,pet_category,category) VALUES (?,?,'TEST_ONLY','CAT','DRY_FOOD')",spu,brand);db.update("INSERT INTO skus(id,spu_id,sku_code,weight_g,package_unit) VALUES (?,?,'TEST_ONLY',1000,'BAG')",sku,spu);db.update("INSERT INTO offers(id,merchant_id,store_id,sku_id,sale_price_fen,fulfillment_sla) VALUES (?,?,?,?,1000,'TEST_ONLY')",offer,m,store,sku);db.update("INSERT INTO inventory_balances(offer_id) VALUES (?)",offer);
  var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.executeWithoutResult(s->{adjust(db,m,offer,actor,0,0,5);db.update("UPDATE inventory_balances SET on_hand_qty=5,version=1 WHERE offer_id=?",offer);});
  Flyway.configure().dataSource(ds).load().migrate();assertEquals(37,db.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE success",Integer.class));assertEquals(5,db.queryForObject("SELECT on_hand_qty FROM inventory_balances WHERE offer_id=?",Integer.class,offer));assertEquals(1,db.queryForObject("SELECT count(*) FROM inventory_adjustments",Integer.class));for(String table:List.of("integration_connections","integration_mappings","integration_stock_movements","integration_stock_acknowledgements","integration_inventory_events","integration_stock_previews","integration_stock_applications"))assertEquals(0,db.queryForObject("SELECT count(*) FROM "+table,Integer.class));
  tx.executeWithoutResult(s->{adjust(db,m,offer,actor,1,5,-1);db.update("UPDATE inventory_balances SET on_hand_qty=4,version=2 WHERE offer_id=?",offer);});assertEquals(1,db.queryForObject("SELECT count(*) FROM integration_stock_movements",Integer.class));assertEquals(-1,db.queryForObject("SELECT delta_qty FROM integration_stock_movements",Integer.class));assertEquals(1,db.queryForObject("SELECT sequence FROM integration_stock_movements",Integer.class));}}
 void adjust(JdbcTemplate db,UUID m,UUID offer,UUID actor,int v,int before,int delta){db.update("INSERT INTO inventory_adjustments(id,merchant_id,offer_id,delta_qty,reason_code,expected_version,before_on_hand_qty,resulting_on_hand_qty,resulting_reserved_qty,resulting_version,actor_id,idempotency_key,payload_hash) VALUES (?,?,?,?,'COUNT_CORRECTION',?,?,?,0,?,?,?,?)",UUID.randomUUID(),m,offer,delta,v,before,before+delta,v+1,actor,UUID.randomUUID().toString(),"a".repeat(64));}

 @Test void upgradeFromV036PreservesExistingB1ConnectionMappingAndDoesNotInventDeliveries()throws Exception{try(var pg=EmbeddedPostgres.builder().start()){var ds=pg.getPostgresDatabase();var db=new JdbcTemplate(ds);Flyway.configure().dataSource(ds).target("36").load().migrate();UUID m=UUID.randomUUID(),store=UUID.randomUUID(),brand=UUID.randomUUID(),spu=UUID.randomUUID(),sku=UUID.randomUUID(),offer=UUID.randomUUID(),actor=UUID.randomUUID(),conn=UUID.randomUUID(),mapping=UUID.randomUUID();
  db.update("INSERT INTO merchant VALUES (?,'TEST_ONLY upgrade','ACTIVE')",m);db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST_ONLY store')",store,m);db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,'TEST_ONLY','TEST_ONLY')",actor,m);db.update("INSERT INTO brands(id,name,source_ref) VALUES (?,'TEST_ONLY','TEST_ONLY')",brand);db.update("INSERT INTO spus(id,brand_id,name,pet_category,category) VALUES (?,?,'TEST_ONLY','CAT','DRY_FOOD')",spu,brand);db.update("INSERT INTO skus(id,spu_id,sku_code,weight_g,package_unit) VALUES (?,?,'TEST_ONLY',1000,'BAG')",sku,spu);db.update("INSERT INTO offers(id,merchant_id,store_id,sku_id,sale_price_fen,fulfillment_sla) VALUES (?,?,?,?,1000,'TEST_ONLY')",offer,m,store,sku);db.update("INSERT INTO inventory_balances(offer_id) VALUES (?)",offer);
  db.update("INSERT INTO integration_connections(id,merchant_id,store_id,label,created_by,created_at) VALUES (?,?,?,'TEST_ONLY_UPGRADE',?,clock_timestamp())",conn,m,store,actor);db.update("INSERT INTO integration_mappings(id,connection_id,offer_id,external_sku,external_warehouse,unit,epoch_sequence,epoch_inventory_version,created_by,created_at) VALUES (?,?,?,'TEST_ONLY_SKU','TEST_ONLY_WH','PIECE',0,0,?,clock_timestamp())",mapping,conn,offer,actor);
  String before=db.queryForObject("SELECT to_jsonb(m)::text FROM integration_mappings m WHERE id=?",String.class,mapping);Flyway.configure().dataSource(ds).load().migrate();assertEquals(37,db.queryForObject("SELECT count(*) FROM flyway_schema_history WHERE success",Integer.class));assertEquals(before,db.queryForObject("SELECT to_jsonb(m)::text FROM integration_mappings m WHERE id=?",String.class,mapping));assertEquals(0,db.queryForObject("SELECT on_hand_qty FROM inventory_balances WHERE offer_id=?",Integer.class,offer));for(String table:List.of("integration_order_deliveries","integration_delivery_attempts","integration_delivery_receipts","integration_delivery_fixture_orders"))assertEquals(0,db.queryForObject("SELECT count(*) FROM "+table,Integer.class));}}
}
